//! The environment map as a light (148:9 §5, "Candidate Generation": when a scene has one, "25% of candidates are
//! instead generated by importance sampling the environment map", through an alias table). The lab's sky
//! (lab/src/environment.rs) at the level lighting reads, each texel weighted by its luminance times its solid angle,
//! so a texel is drawn in proportion to the light it sends (the paper does not say what its weights are; these are
//! the lab's). A sample's direction is kept as two 16-bit coordinates of the image, across and down, so the texel it
//! lies in is read back from its bits exactly; within its texel it is uniform in those coordinates.

use super::alias::{self, AliasColumn};
use glam::Vec3;
use lab::environment::{self as sky, Environment};
use std::f32::consts::PI;
use std::sync::OnceLock;

/// The share of the candidates drawn from the environment map when the room has one (§5).
pub const SHARE: f32 = 0.25;
/// The sample's marker in place of a light index (`RESTIR_ENVIRONMENT`).
pub const MARKER: u32 = u32::MAX - 1;

pub struct Table {
    /// The texels across and down.
    pub size: [usize; 2],
    /// Each texel's radiance, row-major from the top row.
    pub radiance: Vec<Vec3>,
    /// The alias table over the texels.
    pub alias: Vec<AliasColumn>,
    /// Σ luminance × solid angle over the texels: luminance over it is the density per steradian.
    pub norm: f32,
}

/// The table, built once from the lab's sky.
pub fn table() -> &'static Table {
    static TABLE: OnceLock<Table> = OnceLock::new();
    TABLE.get_or_init(|| {
        let e = Environment::get();
        let [w, h] = e.sizes[sky::LIGHTING_LEVEL];
        assert!(
            w.is_power_of_two() && h.is_power_of_two() && w <= 65536 && h <= 65536,
            "the sky's texels must split 16-bit coordinates evenly: {w} x {h}"
        );
        let mut radiance = Vec::with_capacity(w * h);
        let mut weights = Vec::with_capacity(w * h);
        let mut norm = 0.0f64;
        for y in 0..h {
            let omega = texel_solid_angle([w, h], y);
            for x in 0..w {
                // Each texel's weight: the light it sends, its luminance times its solid angle.
                let c = e.texel(sky::LIGHTING_LEVEL, x, y);
                let weight = super::lights::luminance(c) * omega;
                radiance.push(c);
                weights.push(weight);
                norm += f64::from(weight);
            }
        }
        Table {
            size: [w, h],
            radiance,
            alias: alias::table(&weights),
            norm: norm as f32,
        }
    })
}

/// A texel's solid angle (`restirTexelSolidAngle`): its width in azimuth times its band of the sphere, 2 sin θ
/// sin(Δθ / 2) for its row's centre θ and height Δθ (the difference of cosines without the loss of precision).
pub fn texel_solid_angle(size: [usize; 2], row: usize) -> f32 {
    let h = size[1] as f32;
    let theta = (row as f32 + 0.5) / h * PI;
    2.0 * PI / size[0] as f32 * 2.0 * theta.sin() * (0.5 * PI / h).sin()
}

impl Table {
    /// The words the candidate pass reads (`gRestirEnvironment`): per texel, its share's bits and its alias.
    pub fn words(&self) -> Vec<u32> {
        self.alias
            .iter()
            .flat_map(|c| [c.own.to_bits(), c.alias as u32])
            .collect()
    }

    /// The texel a sample lies in, across and down (`restirEnvironmentTexel`).
    pub fn texel(&self, uv: u32) -> [usize; 2] {
        let [w, h] = self.size;
        [
            (uv & 0xffff) as usize / (65536 / w),
            (uv >> 16) as usize / (65536 / h),
        ]
    }

    /// The radiance of the texel a sample lies in, before the sky's level.
    pub fn radiance(&self, uv: u32) -> Vec3 {
        let [x, y] = self.texel(uv);
        self.radiance[y * self.size[0] + x]
    }

    /// The density per steradian of a sample (`restirEnvironmentPdf`): its texel's luminance over the sum, times
    /// the texel's solid angle over that of the sample's own cell of the 16-bit grid, times the cells a texel has.
    pub fn pdf(&self, uv: u32) -> f32 {
        let [w, h] = self.size;
        let [_, row] = self.texel(uv);
        let cells = (65536 / w * (65536 / h)) as f32;
        super::lights::luminance(self.radiance(uv)) / self.norm * texel_solid_angle(self.size, row)
            / (cells * cell_solid_angle(uv))
    }

    /// A sample drawn from four uniform numbers (`restirDrawEnvironment`): a texel's column, the column's part, and
    /// the cell across and down within the texel drawn.
    pub fn draw(&self, u: [f32; 4]) -> u32 {
        let [w, h] = self.size;
        let n = w * h;
        let column = ((u[0] * n as f32) as usize).min(n - 1);
        let i = alias::draw_in(&self.alias, column, u[1]);
        let (across, down) = (65536 / w, 65536 / h);
        let s = (i % w) * across + ((u[2] * across as f32) as usize).min(across - 1);
        let t = (i / w) * down + ((u[3] * down as f32) as usize).min(down - 1);
        (s | (t << 16)) as u32
    }
}

/// The solid angle of a sample's cell of the 16-bit grid, as `texel_solid_angle` for a texel.
pub fn cell_solid_angle(uv: u32) -> f32 {
    2.0 * PI / 65536.0 * 2.0 * cell_theta(uv).sin() * (0.5 * PI / 65536.0).sin()
}

/// The polar angle at the centre of a sample's cell.
fn cell_theta(uv: u32) -> f32 {
    ((uv >> 16) as f32 + 0.5) / 65536.0 * PI
}

/// A sample's direction (`restirEnvironmentDir`): the centre of its cell, as lab/src/environment.rs maps directions
/// to the image (across from the azimuth about +Y, -Z at the centre; down from the polar angle off +Y).
pub fn direction(uv: u32) -> Vec3 {
    let s = ((uv & 0xffff) as f32 + 0.5) / 65536.0;
    let theta = cell_theta(uv);
    let phi = (s - 0.5 - sky::TURN) * 2.0 * PI;
    Vec3::new(
        theta.sin() * phi.sin(),
        theta.cos(),
        -theta.sin() * phi.cos(),
    )
}
